     * <br><br>
     *
     * Example: `2021-02-01`
     * @example 2021-02-01
     **/
    startDateOverride?: string;
    /**
     * Flag to indicate this is a top-up check for prepaid credit top-up billing cycle
     * <br><br>
     * Example: `true`
     * @example true
     */
