import { Logger } from '@nestjs/common';
import { InfluxService } from '../../influx/influx.service.js';
import { Offering } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { InvoicesService } from '../../invoice/invoices.service.js';
import { SchedulerService } from '../../scheduler/scheduler.service.js';
import { CustomerService } from '../../customer/customer.service.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import { InvoiceLineItems, InvoiceLineItem } from '../../invoice/entities/invoice.entity.js';
import { Billing } from '../../billing/entities/billing.entity.js';
import { DatetimeUtils } from '../../utils/datetime.js';
import { AggregatedUsageResponse } from '../../customer/dto/read-customer.dto.js';
import { DimensionOverridesDto } from '../../contract/dto/dimensionOverrides.dto.js';
import { InvoicePaymentTerm } from '../../invoice/entities/InvoicePaymentTerm.js';
import { CreditService } from '../../credit/credit.service.js';
import { SchedulerStatus, schedulerType, SupportedMeasurementFrequencies } from '../../scheduler/dto/scheduler.dto.js';

export class TopUpOffering extends Offering {
    static readonly logger = new Logger(TopUpOffering.name);
    public topUpAmount: number;
    public topUpThreshold: number;
    private topUpSchedulerCreated = false;

    async enroll(subject: string, customer?: ReadCustomerResponseData): Promise<void> {
        await this.registerTopUpScheduler();
        await this.topUp({ customer: customer! });
    }

    async unenroll({ customer, shouldCreditRemainingPlan, isChangeOfPlan }: {
        customer: ReadCustomerResponseData;
        shouldCreditRemainingPlan?: boolean;
        isChangeOfPlan?: boolean;
        creditService?: CreditService;
    }): Promise<void> {
        await this.deregisterTopUpScheduler();
    }

    async topUp({ customer }: { customer: ReadCustomerResponseData }): Promise<void> {
        const creditService = new CreditService(
            this.InfluxService,
            this.customerService,
        );
        const { balance } = await creditService.findCreditBalance({
            businessID: this.businessID,
            customerId: this.customerId,
        }, false);
        const currentBalance = parseFloat(balance);
        const thresholdAmount = this.topUpThreshold * this.topUpAmount;

        if (currentBalance >= thresholdAmount) {
            TopUpOffering.logger.log(`Balance ${currentBalance} >= threshold ${thresholdAmount}, no top-up needed`);
            return;
        }

        const topUpAmount = this.topUpAmount - currentBalance;
        TopUpOffering.logger.log(`Creating top-up invoice for ${this.offeringName}, customer ${this.customerId}, amount: ${topUpAmount}`);

        const lineItems = new InvoiceLineItems();
        lineItems.addLineItem(
            new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, topUpAmount),
        );

        const invoiceInput = {
            businessID: this.businessID,
            customer: customer,
            customerId: this.customerId,
            items: lineItems,
            invoiceDate: new Date().toISOString(),
            currency: Offering.getCurrency({ customer, offering: this }),
        };

        const invoice = await this.invoicesService.buildInvoice(invoiceInput);
        const res = await invoice.generate(this.invoicesService['taxService'], false);

        await creditService.create({
            transactionAmount: topUpAmount.toString(),
            customerId: this.customerId,
            businessID: this.businessID,
            timestamp: new Date().toISOString(),
            metadata: {
                reason: `Top-up for ${this.offeringName}`,
                offeringId: this.offeringId,
                invoiceId: res.invoiceId,
            },
        }, false);

        TopUpOffering.logger.log(`Top-up completed for customer ${this.customerId}, new balance: ${currentBalance + topUpAmount}`);
    }

    async processBilling(
        startDateOverride?: Date,
        endDateOverride?: Date,
        customer?: ReadCustomerResponseData,
        calculateUsage?: boolean,
    ): Promise<string> {
        let startDate: Date;
        let endDate: Date;
        startDate = startDateOverride ? startDateOverride : new Date();
        startDate = DatetimeUtils.beginningOfDay(startDate);
        startDate.setHours(startDate.getHours(), 0, 0, 0);
        endDate = endDateOverride ? endDateOverride : new Date();
        endDate = DatetimeUtils.endOfDay(endDate);
        endDate.setHours(endDate.getHours(), 59, 59, 999);

        const creditService = new CreditService(
            this.InfluxService,
            this.customerService,
        );

        const usage = await this.customerService?.findUsageForCustomer(
            {
                businessID: this.businessID,
                customerId: this.customerId,
                customer,
            },
            {
                startTime: startDate.toISOString(),
                endTime: endDate.toISOString(),
            },
        );

        let totalUsageCost = 0;
        if (usage?.data?.length) {
            for (const usageElement of usage.data) {
                const dimension = this.dimensions.find(d => d.dimensionId === usageElement.dimensionId);
                if (dimension && dimension.consumptionPrice) {
                    const total = Billing.usageToTotal(usageElement as AggregatedUsageResponse, dimension);
                    const usageCost = parseFloat(total) * parseFloat(dimension.consumptionPrice);
                    totalUsageCost += usageCost;
                }
            }
        }

        if (totalUsageCost > 0) {
            await creditService.create({
                transactionAmount: (-totalUsageCost).toString(),
                customerId: this.customerId,
                businessID: this.businessID,
                timestamp: new Date().toISOString(),
                metadata: {
                    reason: `Usage charge for ${this.offeringName}`,
                    offeringId: this.offeringId,
                },
            }, false);

            TopUpOffering.logger.log(`Deducted usage cost ${totalUsageCost} from customer ${this.customerId} wallet`);
        }

        await this.topUp({ customer: customer! });

        return '';
    }

    async offcycleBilling({
        startDate,
        endDate,
        customer,
        invoiceDate,
        invoicePaymentTerm,
        isManual = false,
    }: {
        startDate: Date;
        endDate: Date;
        customer?: ReadCustomerResponseData;
        invoiceDate?: string;
        invoicePaymentTerm?: InvoicePaymentTerm;
        isManual?: boolean;
    }): Promise<string> {
        return '';
    }

    async processFreeTrialEnd({ customer }: { customer: ReadCustomerResponseData }): Promise<string> {
        return '';
    }

    private async registerTopUpScheduler(): Promise<void> {
        if (this.topUpSchedulerCreated || !this.schedulerService) {
            return;
        }

        const schedulerId = `topup-${this.businessID}-${this.offeringId}`;
        try {
            await this.schedulerService.create({
                schedulerID: schedulerId,
                schedulerType: schedulerType.billing,
                schedulerStatus: SchedulerStatus.live,
                scheduleParameters: {
                    businessID: this.businessID,
                    offeringId: this.offeringId,
                    topUpCheck: true,
                } as any,
                rate: SupportedMeasurementFrequencies.everyHour,
                subject: 'system',
                businessID: this.businessID,
            });
            this.topUpSchedulerCreated = true;
            TopUpOffering.logger.log(`Registered top-up scheduler for offering ${this.offeringId}`);
        } catch (e) {
            TopUpOffering.logger.error(`Failed to register top-up scheduler: ${e}`);
        }
    }

    private async deregisterTopUpScheduler(): Promise<void> {
        if (!this.schedulerService) {
            return;
        }

        const schedulerId = `topup-${this.businessID}-${this.offeringId}`;
        try {
            await this.schedulerService.remove({
                schedulerID: schedulerId,
                businessID: this.businessID,
                isBillingQueue: true,
            });
            this.topUpSchedulerCreated = false;
            TopUpOffering.logger.log(`Deregistered top-up scheduler for offering ${this.offeringId}`);
        } catch (e) {
            TopUpOffering.logger.error(`Failed to deregister top-up scheduler: ${e}`);
        }
    }

    constructor({
        offeringName,
        customerId,
        invoicesService,
        schedulerService,
        dimensions,
        businessID,
        customerService,
        freeTrialLength,
        freeTrialEndDate,
        billingCycle,
        currency,
        settings,
        minimumCharge,
        usageOverrides,
        dimensionOverrides,
        offeringId,
        topUpAmount,
        topUpThreshold,
    }: {
        offeringName: string;
        businessID: string;
        customerId: string;
        invoicesService: InvoicesService;
        schedulerService?: SchedulerService;
        customerService?: CustomerService;
        dimensions: ReadOfferingResponseData['dimensions'];
        freeTrialLength?: string;
        freeTrialEndDate?: string;
        billingCycle?: ValidBillingCycles;
        currency?: import('../../offering/dto/SupportedCurrencies.js').SupportedCurrencies;
        settings: ReadSettingsResponseData;
        minimumCharge?: string;
        usageOverrides?: AggregatedUsageResponse[];
        dimensionOverrides?: DimensionOverridesDto[];
        offeringId: string;
        topUpAmount?: string;
        topUpThreshold?: string;
    }) {
        super({
            offeringType: OfferingType.usageBased,
            offeringName,
            customerId,
            invoicesService,
            schedulerService,
            dimensions,
            businessID,
            customerService,
            freeTrialLength,
            freeTrialEndDate,
            billingCycle,
            currency,
            settings,
            minimumCharge,
            usageOverrides,
            dimensionOverrides,
            offeringId,
        });
        this.topUpAmount = parseFloat(topUpAmount || '0');
        this.topUpThreshold = parseFloat(topUpThreshold || '0.2');
    }
}

